begin
  select id into v_owner_id
  from users
  where role = 'owner' and active = true
  order by created_at
  limit 1;

  if v_owner_id is null then
    raise exception 'Vyapar seed requires one active owner profile in public.users.';
  end if;

  if exists (
    select 1 from audit_log
    where action = 'migration' and entity_type = 'vyapar_seed_2026_08'
  ) then
    raise exception 'Vyapar seed has already been applied. It is intentionally one-time and cannot be rerun.';
  end if;

  -- Masters are inserted only when missing, so this is safe for a live system.
  insert into accounts (name, type, holder_name)
  select s.name, s.type, s.holder_name
  from (values
    ('Cash Drawer', 'cash', null::text),
    ('Petty Cash', 'cash', null::text),
    ('Cravory Bank', 'bank', null::text),
    ('Vansh HDFC', 'collection_account', 'Vansh'),
    ('Vansh Kotak', 'collection_account', 'Vansh'),
    ('Meghal IDFC', 'collection_account', 'Meghal'),
    ('Harsh SBI', 'collection_account', 'Harsh'),
    ('Kinchit HSBC', 'collection_account', 'Kinchit')
  ) as s(name, type, holder_name)
  where not exists (select 1 from accounts a where lower(a.name) = lower(s.name));

  insert into expense_categories (name, pl_bucket)
  select s.name, s.pl_bucket
  from (values
    ('Salary', 'operating'), ('Kitchen Operations', 'direct'),
    ('Staff Tiffin / Food Allowance', 'direct'), ('Staff Transport', 'direct'),
    ('Amul Items', 'direct'), ('Vegetables', 'direct'),
    ('Satguru Water Supply', 'operating'), ('Chass Masala', 'direct'),
    ('Electrician', 'operating'), ('Staff Padiki', 'direct'),
    ('Porter', 'operating'), ('Packaging', 'direct'),
    ('Printing & Stationery', 'operating'), ('Tea', 'direct'),
    ('PLUMBER', 'operating')
  ) as s(name, pl_bucket)
  where not exists (select 1 from expense_categories c where lower(c.name) = lower(s.name));

  insert into suppliers (name)
  select s.name
  from (values ('TASTY Vada Pav Raw Material'), ('Water Bottle Vendor'), ('EXTRA BUN PACKET')) as s(name)
  where not exists (select 1 from suppliers p where lower(p.name) = lower(s.name));

  -- Create any source purchase item that is not already in the item master.
  for v_row in select * from jsonb_array_elements(v_data -> 'purchases') loop
    for v_item in select * from jsonb_array_elements(v_row -> 'items') loop
      if not exists (select 1 from items i where lower(i.name) = lower(v_item ->> 'name')) then
        insert into items (name, category, unit, gst_rate, reorder_level)
        values (
          v_item ->> 'name',
          case when coalesce((v_item ->> 'gst_rate')::numeric, 0) > 0 then 'Raw Material' else 'Grocery' end,
          case
            when lower(v_item ->> 'name') in ('vada masalo aalu','lal chatni','green chatni','dabeli masalo','chat masala','red kora masala') then 'kg'
            else coalesce(nullif(lower(v_item ->> 'unit'), ''), 'nos')
          end,
          coalesce((v_item ->> 'gst_rate')::numeric, 0),
          0
        );
      end if;
    end loop;
  end loop;

  select id into v_cash_id from accounts where lower(name) = lower('Cash Drawer') order by created_at limit 1;

  -- Cutover opening cash reported in Vyapar Cash Flow on 16/07/2026.
  insert into transactions (txn_type, txn_date, amount, description, created_by)
  values (
    'opening_balance', v_seed_date, 18000.00,
    'Vyapar migration | source date 16/07/2026 | Cash Flow | INITIAL CASH BY KINCHIT',
    v_owner_id
  ) returning id into v_txn_id;
  insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type)
  values
    (v_txn_id, v_cash_id, 'debit', 18000.00, 'account'),
    (v_txn_id, null, 'credit', 18000.00, 'account');
  insert into audit_log (user_id, action, entity_type, entity_id, after)
  values (v_owner_id, 'migration_create', 'transaction', v_txn_id,
    jsonb_build_object('source','Vyapar Cash Flow','source_date','16/07/2026','seed_date',v_seed_date,'kind','opening_cash'));

  -- Sales: UPI source rows labelled "Unpaid" are treated as collected into the
  -- named collection account, but not necessarily settled to Cravory Bank.
  for v_row in select * from jsonb_array_elements(v_data -> 'sales') loop
    v_amount := (v_row ->> 'amount')::numeric;
    select id into v_account_id from accounts
      where lower(name) = lower(v_row ->> 'account') order by created_at limit 1;
    if v_account_id is null then raise exception 'Missing sale collection account: %', v_row ->> 'account'; end if;
    v_description := concat_ws(' | ',
      'Vyapar migration', 'source date ' || (v_row ->> 'source_date'),
      'sale ref ' || coalesce(nullif(v_row ->> 'ref',''), 'not supplied'),
      nullif(v_row ->> 'description',''),
      'source status ' || (v_row ->> 'source_status'));
    insert into transactions (txn_type, txn_date, amount, description, created_by)
    values ('sale', v_seed_date, v_amount, v_description, v_owner_id) returning id into v_txn_id;
    insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type)
    values
      (v_txn_id, v_account_id, 'debit', v_amount, 'revenue'),
      (v_txn_id, null, 'credit', v_amount, 'revenue');
    insert into sale_details (transaction_id, payment_method, collection_account_id)
    values (v_txn_id, v_row ->> 'payment_method', v_account_id);
    insert into audit_log (user_id, action, entity_type, entity_id, after)
    values (v_owner_id, 'migration_create', 'transaction', v_txn_id,
      jsonb_build_object('source','Vyapar All Transactions','source_date',v_row->>'source_date',
        'source_ref',v_row->>'ref','seed_date',v_seed_date,'source_status',v_row->>'source_status'));
  end loop;

  -- Expenses: financial records are complete. Itemized expense lines are not
  -- fabricated because the report does not reliably provide matching details.
  for v_row in select * from jsonb_array_elements(v_data -> 'expenses') loop
    v_amount := (v_row ->> 'amount')::numeric;
    select id into v_category_id from expense_categories
      where lower(name) = lower(v_row ->> 'category') order by created_at limit 1;
    select id into v_account_id from accounts
      where lower(name) = lower(v_row ->> 'account') order by created_at limit 1;
    if v_category_id is null or v_account_id is null then
      raise exception 'Missing expense category/account for source expense: % / %', v_row->>'category', v_row->>'account';
    end if;
    v_description := concat_ws(' | ', 'Vyapar migration', 'source date ' || (v_row ->> 'source_date'),
      nullif(v_row ->> 'description',''), 'category ' || (v_row ->> 'category'));
    insert into transactions (txn_type, txn_date, amount, description, created_by)
    values ('expense', v_seed_date, v_amount, v_description, v_owner_id) returning id into v_txn_id;
    insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type, counterparty_id)
    values
      (v_txn_id, null, 'debit', v_amount, 'expense_category', v_category_id),
      (v_txn_id, v_account_id, 'credit', v_amount, 'expense_category', v_category_id);
    insert into expense_details (transaction_id, category_id, paid_from_account_id)
    values (v_txn_id, v_category_id, v_account_id);
    insert into audit_log (user_id, action, entity_type, entity_id, after)
    values (v_owner_id, 'migration_create', 'transaction', v_txn_id,
      jsonb_build_object('source','Vyapar All Transactions','source_date',v_row->>'source_date',
        'seed_date',v_seed_date,'category',v_row->>'category'));
  end loop;

  -- Purchases and inventory: each source item line creates both a purchase line
  -- and a stock movement. The three source records without item detail stay
  -- financially correct but deliberately create no stock movement.
  for v_row in select * from jsonb_array_elements(v_data -> 'purchases') loop
    v_amount := (v_row ->> 'amount')::numeric;
    v_paid_amount := (v_row ->> 'paid_amount')::numeric;
    select id into v_supplier_id from suppliers
      where lower(name) = lower(v_row ->> 'supplier') order by created_at limit 1;
    select id into v_account_id from accounts
      where lower(name) = lower(v_row ->> 'paid_from') order by created_at limit 1;
    if v_supplier_id is null or v_account_id is null then
      raise exception 'Missing supplier/payment account for source purchase: % / %', v_row->>'supplier', v_row->>'paid_from';
    end if;
    v_description := concat_ws(' | ', 'Vyapar migration', 'source date ' || (v_row ->> 'source_date'),
      'purchase ref ' || coalesce(nullif(v_row ->> 'ref',''), 'not supplied'),
      nullif(v_row ->> 'description',''), 'source status ' || (v_row ->> 'source_status'),
      case when (v_row ->> 'item_detail_missing')::boolean then 'ITEM DETAIL MISSING IN SOURCE REPORT' end);
    insert into transactions (txn_type, txn_date, amount, description, created_by)
    values ('purchase', v_seed_date, v_amount, v_description, v_owner_id) returning id into v_txn_id;
    insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type, counterparty_id)
    values
      (v_txn_id, null, 'debit', v_amount, 'inventory', null),
      (v_txn_id, null, 'credit', v_amount, 'supplier', v_supplier_id);
    if v_paid_amount > 0 then
      insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type, counterparty_id)
      values
        (v_txn_id, null, 'debit', v_paid_amount, 'supplier', v_supplier_id),
        (v_txn_id, v_account_id, 'credit', v_paid_amount, 'supplier', v_supplier_id);
    end if;
    insert into purchase_details (transaction_id, supplier_id, paid_amount)
    values (v_txn_id, v_supplier_id, v_paid_amount);
    for v_item in select * from jsonb_array_elements(v_row -> 'items') loop
      select id into v_item_id from items where lower(name) = lower(v_item ->> 'name') order by created_at limit 1;
      if v_item_id is null then raise exception 'Missing source item %', v_item ->> 'name'; end if;
      insert into purchase_items (transaction_id, item_id, quantity, rate, gst_amount, amount)
      values (v_txn_id, v_item_id, (v_item->>'quantity')::numeric, (v_item->>'rate')::numeric,
        (v_item->>'gst_amount')::numeric, (v_item->>'amount')::numeric);
      insert into stock_movements (item_id, transaction_id, movement_type, quantity, rate, reason)
      values (v_item_id, v_txn_id, 'purchase', (v_item->>'quantity')::numeric,
        (v_item->>'rate')::numeric, 'Vyapar migration source date ' || (v_row->>'source_date'));
    end loop;
    insert into audit_log (user_id, action, entity_type, entity_id, after)
    values (v_owner_id, 'migration_create', 'transaction', v_txn_id,
      jsonb_build_object('source','Vyapar All Transactions and Item Details','source_date',v_row->>'source_date',
        'source_ref',v_row->>'ref','seed_date',v_seed_date,
        'item_detail_missing',(v_row->>'item_detail_missing')::boolean));
  end loop;

  -- Payment-in rows are UPI settlements into the business bank account.
  for v_row in select * from jsonb_array_elements(v_data -> 'settlements') loop
    v_amount := (v_row ->> 'amount')::numeric;
    select id into v_account_id from accounts where lower(name) = lower(v_row ->> 'collection_account') order by created_at limit 1;
    select id into v_cash_id from accounts where lower(name) = lower(v_row ->> 'settled_to') order by created_at limit 1;
    if v_account_id is null or v_cash_id is null then raise exception 'Missing settlement account.'; end if;
    insert into transactions (txn_type, txn_date, amount, description, created_by)
    values ('settlement', v_seed_date, v_amount,
      'Vyapar migration | source date ' || (v_row->>'source_date') || ' | payment-in ref ' || (v_row->>'ref'),
      v_owner_id) returning id into v_txn_id;
    insert into ledger_entries (transaction_id, account_id, entry_side, amount, counterparty_type)
    values
      (v_txn_id, v_cash_id, 'debit', v_amount, 'account'),
      (v_txn_id, v_account_id, 'credit', v_amount, 'account');
    insert into settlement_details (transaction_id, collection_account_id, settled_to_account_id)
    values (v_txn_id, v_account_id, v_cash_id);
    insert into audit_log (user_id, action, entity_type, entity_id, after)
    values (v_owner_id, 'migration_create', 'transaction', v_txn_id,
      jsonb_build_object('source','Vyapar All Transactions','source_date',v_row->>'source_date',
        'source_ref',v_row->>'ref','seed_date',v_seed_date,'kind','upi_settlement'));
  end loop;

  insert into audit_log (user_id, action, entity_type, after)
  values (v_owner_id, 'migration', 'vyapar_seed_2026_08',
    jsonb_build_object(
      'source','Vyapar reports supplied by owner',
      'seed_date',v_seed_date,
      'sales',jsonb_array_length(v_data->'sales'),
      'purchases',jsonb_array_length(v_data->'purchases'),
      'expenses',jsonb_array_length(v_data->'expenses'),
      'settlements',jsonb_array_length(v_data->'settlements'),
      'opening_cash',18000.00,
      'purchase_records_missing_item_detail',3,
      'note','Original report dates/references are stored in descriptions and audit metadata.'
    ));
end $$;

commit;
